+                          ShowMoveRight="ShowMoveRight"
+                          OnMoveLeft="() => OnMoveTask.InvokeAsync((task.Id, MoveLeftStatus!))"
+                          OnMoveRight="() => OnMoveTask.InvokeAsync((task.Id, MoveRightStatus!))" />
+            }
+
+            @if (showForm)
+            {
+                <AddTaskForm OnSave="HandleSave" OnCancel="() => showForm = false" />
+            }
+        </div>
+        <div class="card-footer">
+            <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => showForm = true">
+                + Add Task
+            </button>
+        </div>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public string ColumnName { get; set; } = string.Empty;
+    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
+    [Parameter] public bool ShowMoveLeft { get; set; }
+    [Parameter] public bool ShowMoveRight { get; set; }
+    [Parameter] public string? MoveLeftStatus { get; set; }
+    [Parameter] public string? MoveRightStatus { get; set; }
+    [Parameter] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
+    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }
+
+    private bool showForm;
+
+    private async Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) data)
+    {
+        await OnAddTask.InvokeAsync(data);
+        showForm = false;
+    }
+}
